import{_ as o,V as l,W as i,X as u,Z as n,$ as a,a0 as d,a1 as s,Y as t,F as e}from"./framework-b1bd8911.js";const k={},r=t(`<h1 id="base-plugin-公共工具类速查" tabindex="-1"><a class="header-anchor" href="#base-plugin-公共工具类速查" aria-hidden="true">#</a> base-plugin 公共工具类速查</h1><blockquote><p>QuickMedia 各插件的公共基础库，本文按分类整理 base-plugin 内所有工具类的典型用法</p></blockquote><p>base-plugin 在 QuickMedia 里的定位是「内部依赖库」：image-plugin、qrcode-plugin、markdown-plugin 等插件对文件、图片、gif、http 的操作，底层都是通过它完成的，日常大概率是随其他插件<strong>间接引入</strong>，基本不会单独依赖。</p><p>不过这套工具类本身写得挺通用，想在业务里直接用也没问题，maven 坐标如下（也可以直接看源码，每个类都很短）：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.github.liuyueyi.media<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>base-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.1.0<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,5),m=t(`<p>下面按分类逐个过一遍，所有方法签名均以源码为准。</p><h2 id="_1-文件读取-filereadutil" tabindex="-1"><a class="header-anchor" href="#_1-文件读取-filereadutil" aria-hidden="true">#</a> 1. 文件读取：FileReadUtil</h2><p>最核心的一个方法，<code>getStreamByFileName</code> 统一了四种文件来源，传什么路径它自己判断：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 根据路径获取输入流：网络地址 / 绝对路径 / ~/用户目录 / classpath 相对路径</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">InputStream</span> <span class="token function">getStreamByFileName</span><span class="token punctuation">(</span><span class="token class-name">String</span> fileName<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>判断规则（源码）：</p><ul><li><code>http</code> 开头 → 走 <code>HttpUtil.downFile</code> 从网络下载</li><li>绝对路径（win 下含 <code>:</code> 或 <code>\\\\</code> 开头，其他系统 <code>/</code> 开头）→ 直接打开本地文件</li><li><code>~</code> 开头 → 替换成用户主目录后打开</li><li>其余 → 作为 classpath 相对路径，从 <code>ClassLoader</code> 里找资源</li></ul><p>在这个基础之上有几个常用封装：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 整个文件读成一个字符串（按行读取后用 \\n 拼接）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">readAll</span><span class="token punctuation">(</span><span class="token class-name">String</span> fileName<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>

<span class="token comment">// 分别以字节/字符/行为单位打开读取器，均支持上面四种路径</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">InputStream</span> <span class="token function">createByteRead</span><span class="token punctuation">(</span><span class="token class-name">String</span> fileName<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Reader</span> <span class="token function">createCharRead</span><span class="token punctuation">(</span><span class="token class-name">String</span> fileName<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedReader</span> <span class="token function">createLineRead</span><span class="token punctuation">(</span><span class="token class-name">String</span> fileName<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>典型用法，比如在 qrcode 插件里读取模板文件：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">String</span> content <span class="token operator">=</span> <span class="token class-name">FileReadUtil</span><span class="token punctuation">.</span><span class="token function">readAll</span><span class="token punctuation">(</span><span class="token string">&quot;svg/愤怒小猪svg.template&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这里传的是相对路径，实际就是从 <code>src/main/resources</code>（或 jar 包内）读取。</p><p>还有一个可能用得上的小能力——<strong>魔数识别</strong>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 读取文件头 28 字节，转成 16 进制字符串</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">getMagicNum</span><span class="token punctuation">(</span><span class="token class-name">String</span> file<span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">getMagicNum</span><span class="token punctuation">(</span><span class="token class-name">ByteArrayInputStream</span> inputStream<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>jpeg 的头是 <code>FFD8FF</code>，png 是 <code>89504E47</code>，gif 是 <code>47494638</code>，webp 是 <code>52494646</code>。想验证一个文件是不是真的图片（而非改了后缀的假货），靠后缀靠不住，靠魔数才靠谱。</p><h2 id="_2-文件写入-filewriteutil" tabindex="-1"><a class="header-anchor" href="#_2-文件写入-filewriteutil" aria-hidden="true">#</a> 2. 文件写入：FileWriteUtil</h2><p>设计上有点意思的是它的<strong>临时目录约定</strong>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 临时目录：/tmp/quickmedia/（windows 为 C://tmp/quickmedia/）+ yyyyMMdd</span>
<span class="token comment">// 优先读取系统属性 quick.media.tmp.path，配置了就用它</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">getTmpPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>也就是说 quick-media 各插件落地的临时文件，默认在 <code>/tmp/quickmedia/20261112/</code> 这类目录下；想换地方，启动时加 <code>-Dquick.media.tmp.path=/data/quickmedia/</code> 即可，不用改代码。</p><p>保存文件走 <code>saveFile</code>，支持三种入参类型：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// src 支持 String(路径，含网络url) / URI / InputStream，统一保存并返回文件信息</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">T</span><span class="token punctuation">&gt;</span></span> <span class="token class-name">FileInfo</span> <span class="token function">saveFile</span><span class="token punctuation">(</span><span class="token class-name">T</span> src<span class="token punctuation">,</span> <span class="token class-name">String</span> inputType<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">Exception</span>

<span class="token comment">// 流保存到临时目录，文件名 = 时间戳_随机数</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">FileInfo</span> <span class="token function">saveFileByStream</span><span class="token punctuation">(</span><span class="token class-name">InputStream</span> inputStream<span class="token punctuation">,</span> <span class="token class-name">String</span> fileType<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">Exception</span>

<span class="token comment">// 文本保存</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">saveContent</span><span class="token punctuation">(</span><span class="token class-name">FileInfo</span> fileInfo<span class="token punctuation">,</span> <span class="token class-name">String</span> content<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">FileNotFoundException</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">saveContent</span><span class="token punctuation">(</span><span class="token class-name">File</span> file<span class="token punctuation">,</span> <span class="token class-name">String</span> content<span class="token punctuation">)</span>

<span class="token comment">// 递归创建目录（各插件输出文件前都会先调它）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">mkDir</span><span class="token punctuation">(</span><span class="token class-name">File</span> path<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">FileNotFoundException</span>

<span class="token comment">// 解析绝对路径，得到 目录 + 文件名 + 后缀</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">FileInfo</span> <span class="token function">parseAbsFileToFileInfo</span><span class="token punctuation">(</span><span class="token class-name">String</span> absFile<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>FileInfo</code> 内部就三个字段 <code>path / filename / fileType</code>，用 <code>getAbsFile()</code> 可以拼回全路径。</p><h2 id="_3-文件路径与类型-basicfileutil" tabindex="-1"><a class="header-anchor" href="#_3-文件路径与类型-basicfileutil" aria-hidden="true">#</a> 3. 文件路径与类型：BasicFileUtil</h2><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 是否绝对路径（自动区分 win/mac/linux）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">boolean</span> <span class="token function">isAbsFile</span><span class="token punctuation">(</span><span class="token class-name">String</span> fileName<span class="token punctuation">)</span>

<span class="token comment">// ~/xxx 转换为绝对路径</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">parseHomeDir2AbsDir</span><span class="token punctuation">(</span><span class="token class-name">String</span> path<span class="token punctuation">)</span>

<span class="token comment">// 根据文件魔数判断文件类型，返回 MediaType 枚举</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">MediaType</span> <span class="token function">getMediaType</span><span class="token punctuation">(</span><span class="token class-name">String</span> path<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>MediaType</code>（<code>constants</code> 包下）是个枚举，定义了 jpg/gif/png/webp/mp3/wav/mp4 等常见格式的 <code>后缀、mime、魔数、data-uri 前缀</code> 四件套，配合 <code>FileReadUtil.getMagicNum</code> 就能实现「只认内容不认后缀」的文件类型识别。</p><h2 id="_4-图片加载-imageloadutil" tabindex="-1"><a class="header-anchor" href="#_4-图片加载-imageloadutil" aria-hidden="true">#</a> 4. 图片加载：ImageLoadUtil</h2><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 按路径加载图片，路径规则与 FileReadUtil 一致（本地/网络/classpath），ico 格式走 image4j 解析</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">getImageByPath</span><span class="token punctuation">(</span><span class="token class-name">String</span> path<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>

<span class="token comment">// 按路径加载 gif，返回 GifDecoder</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">GifDecoder</span> <span class="token function">getGifByPath</span><span class="token punctuation">(</span><span class="token class-name">String</span> path<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个方法在各个插件里出场率极高，比如 qrcode 插件里设置 logo：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">BufferedImage</span> logo <span class="token operator">=</span> <span class="token class-name">ImageLoadUtil</span><span class="token punctuation">.</span><span class="token function">getImageByPath</span><span class="token punctuation">(</span><span class="token string">&quot;logo.jpg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// classpath</span>
<span class="token class-name">BufferedImage</span> netImg <span class="token operator">=</span> <span class="token class-name">ImageLoadUtil</span><span class="token punctuation">.</span><span class="token function">getImageByPath</span><span class="token punctuation">(</span><span class="token string">&quot;https://blog.hhui.top/hexblog/images/avatar.jpg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 网络</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>注意：加载 ico 需要 <code>image4j</code> 依赖，它在 base-plugin 的 pom 里是 <code>provided</code> scope（不会传递），需要解析 ico 的项目要自己显式引入 <code>org.jclarion:image4j:0.7</code>。</p><h2 id="_5-图片操作-imageoperateutil" tabindex="-1"><a class="header-anchor" href="#_5-图片操作-imageoperateutil" aria-hidden="true">#</a> 5. 图片操作：ImageOperateUtil</h2><p>主要服务于「logo 处理」这类场景：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 矩形图变正圆图（自动居中裁剪出最大的正方形区域再转圆），可加圆形边框</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">makeRoundImg</span><span class="token punctuation">(</span><span class="token class-name">BufferedImage</span> image<span class="token punctuation">,</span> <span class="token keyword">boolean</span> borderEnable<span class="token punctuation">,</span> <span class="token class-name">Color</span> borderColor<span class="token punctuation">)</span>

<span class="token comment">// 按指定区域 + 圆角弧度生成圆角图</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">makeRoundImg</span><span class="token punctuation">(</span><span class="token class-name">BufferedImage</span> image<span class="token punctuation">,</span> <span class="token class-name">Rectangle</span> rectangle<span class="token punctuation">,</span> <span class="token keyword">int</span> cornerRadius<span class="token punctuation">)</span>

<span class="token comment">// 生成圆角图（整图圆角，常用于二维码圆角）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">makeRoundedCorner</span><span class="token punctuation">(</span><span class="token class-name">BufferedImage</span> image<span class="token punctuation">,</span> <span class="token keyword">int</span> cornerRadius<span class="token punctuation">)</span>

<span class="token comment">// 生成带圆角边框的图片</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">makeRoundBorder</span><span class="token punctuation">(</span><span class="token class-name">BufferedImage</span> image<span class="token punctuation">,</span> <span class="token keyword">int</span> cornerRadius<span class="token punctuation">,</span> <span class="token class-name">Color</span> color<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>cornerRadius</code> 的取值，源码注释里给的实测建议是<strong>图片宽度的 1/4</strong>，传 0 表示直角。</p><h2 id="_6-绘图基础-graphicutil" tabindex="-1"><a class="header-anchor" href="#_6-绘图基础-graphicutil" aria-hidden="true">#</a> 6. 绘图基础：GraphicUtil</h2><p>这个类在 QuickMedia 里几乎是「绘图画布」的标配入口，最常用的是 <code>getG2d</code>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 获取 Graphics2D，内部已经配好了抗锯齿、高质量渲染等 RenderingHints</span>
<span class="token comment">// 手绘时强烈建议用它拿画笔，否则画出来的线条边缘会有明显的锯齿感</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Graphics2D</span> <span class="token function">getG2d</span><span class="token punctuation">(</span><span class="token class-name">BufferedImage</span> bf<span class="token punctuation">)</span>

<span class="token comment">// 创建画布，可选填充底色、在 (offsetX, offsetY) 位置贴一张底图</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">createImg</span><span class="token punctuation">(</span><span class="token keyword">int</span> w<span class="token punctuation">,</span> <span class="token keyword">int</span> h<span class="token punctuation">,</span> <span class="token keyword">int</span> type<span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">createImg</span><span class="token punctuation">(</span><span class="token keyword">int</span> w<span class="token punctuation">,</span> <span class="token keyword">int</span> h<span class="token punctuation">,</span> <span class="token class-name">BufferedImage</span> img<span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">createImg</span><span class="token punctuation">(</span><span class="token keyword">int</span> w<span class="token punctuation">,</span> <span class="token keyword">int</span> h<span class="token punctuation">,</span> <span class="token keyword">int</span> offsetX<span class="token punctuation">,</span> <span class="token keyword">int</span> offsetY<span class="token punctuation">,</span> <span class="token class-name">BufferedImage</span> img<span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">createImg</span><span class="token punctuation">(</span><span class="token keyword">int</span> w<span class="token punctuation">,</span> <span class="token keyword">int</span> h<span class="token punctuation">,</span> <span class="token keyword">int</span> offsetX<span class="token punctuation">,</span> <span class="token keyword">int</span> offsetY<span class="token punctuation">,</span> <span class="token class-name">BufferedImage</span> img<span class="token punctuation">,</span> <span class="token class-name">Color</span> fillColor<span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">createImg</span><span class="token punctuation">(</span><span class="token keyword">int</span> w<span class="token punctuation">,</span> <span class="token keyword">int</span> h<span class="token punctuation">,</span> <span class="token keyword">int</span> offsetX<span class="token punctuation">,</span> <span class="token keyword">int</span> offsetY<span class="token punctuation">,</span> <span class="token keyword">int</span> imgType<span class="token punctuation">,</span> <span class="token class-name">BufferedImage</span> img<span class="token punctuation">,</span> <span class="token class-name">Color</span> fillColor<span class="token punctuation">)</span>

<span class="token comment">// 缩放</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">scaleImg</span><span class="token punctuation">(</span><span class="token keyword">int</span> w<span class="token punctuation">,</span> <span class="token keyword">int</span> h<span class="token punctuation">,</span> <span class="token class-name">BufferedImage</span> img<span class="token punctuation">)</span>   <span class="token comment">// 拉伸到指定宽高</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Image</span> <span class="token function">smoothScale</span><span class="token punctuation">(</span><span class="token class-name">BufferedImage</span> img<span class="token punctuation">,</span> <span class="token keyword">int</span> w<span class="token punctuation">,</span> <span class="token keyword">int</span> h<span class="token punctuation">)</span>        <span class="token comment">// 平滑缩放（尺寸相同则原样返回）</span>

<span class="token comment">// png 转 jpg（透明区域用指定底色填充，避免 jpg 不支持透明出现异常色块）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">pngToJpg</span><span class="token punctuation">(</span><span class="token class-name">BufferedImage</span> img<span class="token punctuation">,</span> <span class="token class-name">Color</span> bg<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>pngToJpg</code> 是个容易忽略但很实用的方法：jpg 不支持透明通道，直接把带透明的 png 写成 jpg，透明区域往往会渲染成奇怪的偏红色调，先用它填个底色再输出就正常了。</p><h2 id="_7-颜色处理-colorutil" tabindex="-1"><a class="header-anchor" href="#_7-颜色处理-colorutil" aria-hidden="true">#</a> 7. 颜色处理：ColorUtil</h2><p>QuickMedia 的插件支持多种传参格式的颜色（<code>Color</code> 对象、int、字符串），互转逻辑都收在这个类里：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// int 颜色转 Color：0xffffffff，高两位透明度，后面依次 R G B</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Color</span> <span class="token function">int2color</span><span class="token punctuation">(</span><span class="token keyword">int</span> color<span class="token punctuation">)</span>

<span class="token comment">// html 风格颜色转 Color，支持 #rgb / #rgba / #rrggbb / #rrggbbaa 四种格式</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Color</span> <span class="token function">html2color</span><span class="token punctuation">(</span><span class="token class-name">String</span> color<span class="token punctuation">)</span>

<span class="token comment">// 字符串颜色统一入口：# 开头走 html，0x 开头走十六进制，纯数字走十进制</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Color</span> <span class="token function">str2color</span><span class="token punctuation">(</span><span class="token class-name">String</span> color<span class="token punctuation">)</span>

<span class="token comment">// 反向转换：Color 转 html 格式字符串</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">int2htmlColor</span><span class="token punctuation">(</span><span class="token keyword">int</span> color<span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">color2htmlColor</span><span class="token punctuation">(</span><span class="token class-name">Color</span> color<span class="token punctuation">)</span>

<span class="token comment">// 两个预置颜色</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Color</span> <span class="token constant">OPACITY</span><span class="token punctuation">;</span>    <span class="token comment">// 全透明</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Color</span> <span class="token constant">OFF_WHITE</span><span class="token punctuation">;</span>  <span class="token comment">// 米黄色 0xFFF7EED6</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>举个对得上的测试 case（<code>ColorUtilTest#testHtml2Color</code>）：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">ColorUtil</span><span class="token punctuation">.</span><span class="token function">html2color</span><span class="token punctuation">(</span><span class="token string">&quot;#a10&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// r=0xaa, g=0x11, b=0x00</span>
<span class="token class-name">ColorUtil</span><span class="token punctuation">.</span><span class="token function">html2color</span><span class="token punctuation">(</span><span class="token string">&quot;#aa1100ff&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 八位，最后两位是透明度 0xff</span>
<span class="token class-name">ColorUtil</span><span class="token punctuation">.</span><span class="token function">int2color</span><span class="token punctuation">(</span><span class="token number">0xffcfccc9</span><span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// int 写法，注意别丢掉 0xff 的透明度位</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>一个老生常谈但确实容易踩的坑：用 int 表示颜色时，<strong>最高两位是透明度</strong>，如果写成 <code>0x2e317c</code> 这种六位的，实际透明度是 0，画出来会「看不见」，记得带上 <code>0xff</code> 前缀，或者干脆用 <code>#</code> 字符串格式。</p><h2 id="_8-gif-编解码-gifhelper-gifdecoder-gifencoder" tabindex="-1"><a class="header-anchor" href="#_8-gif-编解码-gifhelper-gifdecoder-gifencoder" aria-hidden="true">#</a> 8. gif 编解码：GifHelper / GifDecoder / GifEncoder</h2><p>gif 相关的能力都封装在 <code>GifHelper</code> 这个门面里，日常用它就够了：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 加载 gif（会先校验文件魔数，不是 gif 直接抛异常）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">GifDecoder</span> <span class="token function">loadGif</span><span class="token punctuation">(</span><span class="token class-name">String</span> gif<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>

<span class="token comment">// 加载 gif，把每一帧塞进 list，返回帧间最小延时（毫秒）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">int</span> <span class="token function">loadGif</span><span class="token punctuation">(</span><span class="token class-name">String</span> gif<span class="token punctuation">,</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">BufferedImage</span><span class="token punctuation">&gt;</span></span> list<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">int</span> <span class="token function">loadGif</span><span class="token punctuation">(</span><span class="token class-name">InputStream</span> stream<span class="token punctuation">,</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">BufferedImage</span><span class="token punctuation">&gt;</span></span> list<span class="token punctuation">)</span>

<span class="token comment">// 把一组帧合成 gif 输出到文件或流</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">saveGif</span><span class="token punctuation">(</span><span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">BufferedImage</span><span class="token punctuation">&gt;</span></span> frames<span class="token punctuation">,</span> <span class="token keyword">int</span> delay<span class="token punctuation">,</span> <span class="token class-name">String</span> out<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">FileNotFoundException</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">saveGif</span><span class="token punctuation">(</span><span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">BufferedImage</span><span class="token punctuation">&gt;</span></span> frames<span class="token punctuation">,</span> <span class="token keyword">int</span> delay<span class="token punctuation">,</span> <span class="token class-name">OutputStream</span> out<span class="token punctuation">)</span>

<span class="token comment">// 每帧可以单独指定延时的输出方式</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">saveGif</span><span class="token punctuation">(</span><span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">ImmutablePair</span><span class="token punctuation">&lt;</span><span class="token class-name">BufferedImage</span><span class="token punctuation">,</span> <span class="token class-name">Integer</span><span class="token punctuation">&gt;</span><span class="token punctuation">&gt;</span></span> frames<span class="token punctuation">,</span> <span class="token class-name">OutputStream</span> out<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>组合起来就能实现「拆帧改帧再合成」这种操作，quick-media 里动图相关插件的底层就是这套：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">BufferedImage</span><span class="token punctuation">&gt;</span></span> frames <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayList</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">int</span> delay <span class="token operator">=</span> <span class="token class-name">GifHelper</span><span class="token punctuation">.</span><span class="token function">loadGif</span><span class="token punctuation">(</span><span class="token string">&quot;demo.gif&quot;</span><span class="token punctuation">,</span> frames<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// ... 对每一帧做些处理 ...</span>
<span class="token class-name">GifHelper</span><span class="token punctuation">.</span><span class="token function">saveGif</span><span class="token punctuation">(</span>frames<span class="token punctuation">,</span> delay<span class="token punctuation">,</span> <span class="token string">&quot;/tmp/out.gif&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果想更细粒度地控制，也可以直接用底层的两个类：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// GifDecoder：逐帧读取</span>
<span class="token class-name">GifDecoder</span> decoder <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">GifDecoder</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
decoder<span class="token punctuation">.</span><span class="token function">read</span><span class="token punctuation">(</span>inputStream<span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// 返回状态码：STATUS_OK / STATUS_FORMAT_ERROR / STATUS_OPEN_ERROR</span>
decoder<span class="token punctuation">.</span><span class="token function">getFrameCount</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>              <span class="token comment">// 总帧数</span>
decoder<span class="token punctuation">.</span><span class="token function">getFrame</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                  <span class="token comment">// 第 n 帧</span>
decoder<span class="token punctuation">.</span><span class="token function">getDelay</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                  <span class="token comment">// 第 n 帧延时（毫秒）</span>
decoder<span class="token punctuation">.</span><span class="token function">getLoopCount</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>               <span class="token comment">// 循环次数，0 表示无限循环</span>

<span class="token comment">// GifEncoder：逐帧编码（经典写法见类头注释）</span>
<span class="token class-name">GifEncoder</span> encoder <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">GifEncoder</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
encoder<span class="token punctuation">.</span><span class="token function">start</span><span class="token punctuation">(</span>outputStream<span class="token punctuation">)</span><span class="token punctuation">;</span>
encoder<span class="token punctuation">.</span><span class="token function">setRepeat</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                 <span class="token comment">// 0 = 无限循环</span>
encoder<span class="token punctuation">.</span><span class="token function">setDelay</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                <span class="token comment">// 帧延时，毫秒</span>
encoder<span class="token punctuation">.</span><span class="token function">addFrame</span><span class="token punctuation">(</span>img<span class="token punctuation">)</span><span class="token punctuation">;</span>                <span class="token comment">// 逐帧添加</span>
encoder<span class="token punctuation">.</span><span class="token function">finish</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_9-http-下载-httputil" tabindex="-1"><a class="header-anchor" href="#_9-http-下载-httputil" aria-hidden="true">#</a> 9. http 下载：HttpUtil</h2><p>就一个能力：把网络资源下成输入流。</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">InputStream</span> <span class="token function">downFile</span><span class="token punctuation">(</span><span class="token class-name">String</span> src<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">InputStream</span> <span class="token function">downFile</span><span class="token punctuation">(</span><span class="token class-name">URI</span> uri<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>实现上用的是 httpclient 的 fluent API，GET 请求，自动带上了浏览器 UA；非 200 响应直接抛 <code>FileNotFoundException</code>。<code>FileReadUtil.getStreamByFileName</code> 里识别到 <code>http</code> 开头的路径，最终就是落到这个方法上。</p><h2 id="_10-io-小工具-ioutil" tabindex="-1"><a class="header-anchor" href="#_10-io-小工具-ioutil" aria-hidden="true">#</a> 10. IO 小工具：IoUtil</h2><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 把任意输入流转成字节数组流，好处是流可以重复消费（mark/reset 不支持的场景也 ok）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">ByteArrayInputStream</span> <span class="token function">toByteArrayInputStream</span><span class="token punctuation">(</span><span class="token class-name">InputStream</span> inputStream<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>

<span class="token comment">// 流内容读成字符串，方便打印日志</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">readToString</span><span class="token punctuation">(</span><span class="token class-name">InputStream</span> inputStream<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>toByteArrayInputStream</code> 在「一个流要读多次」的场景很常用，比如 <code>GifHelper.loadGif</code> 里先用流读魔数、再用同一个流解码 gif，中间就是靠它做的流复制。</p><h2 id="_11-base64-与-data-uri-base64util-domutil" tabindex="-1"><a class="header-anchor" href="#_11-base64-与-data-uri-base64util-domutil" aria-hidden="true">#</a> 11. base64 与 data-uri：Base64Util / DomUtil</h2><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// BufferedImage 编码为 base64 字符串（imgType 如 &quot;png&quot;、&quot;jpg&quot;）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">encode</span><span class="token punctuation">(</span><span class="token class-name">BufferedImage</span> bufferedImage<span class="token punctuation">,</span> <span class="token class-name">String</span> imgType<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">encode</span><span class="token punctuation">(</span><span class="token class-name">ByteArrayOutputStream</span> outputStream<span class="token punctuation">)</span>

<span class="token comment">// base64 字符串解码回 BufferedImage</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">decode2Img</span><span class="token punctuation">(</span><span class="token class-name">String</span> base64<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>DomUtil</code> 只有一个方法，把 base64 拼成 html 能直接用的 data-uri：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">DomUtil</span><span class="token punctuation">.</span><span class="token function">toDomSrc</span><span class="token punctuation">(</span><span class="token class-name">Base64Util</span><span class="token punctuation">.</span><span class="token function">encode</span><span class="token punctuation">(</span>img<span class="token punctuation">,</span> <span class="token string">&quot;png&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">MediaType<span class="token punctuation">.</span>ImagePng</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 得到 data:image/png;base64,xxx...，可以直接塞进 &lt;img src=&quot;...&quot;&gt; 或 json 响应里</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>这套组合在 phantom-plugin 的 html 转图片、qrcode 插件的 base64 二维码输出里都有实际应用。</p><h2 id="_12-系统与进程-osutil-numutil-processutil" tabindex="-1"><a class="header-anchor" href="#_12-系统与进程-osutil-numutil-processutil" aria-hidden="true">#</a> 12. 系统与进程：OSUtil / NumUtil / ProcessUtil</h2><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// OSUtil：判断是否 windows 系统（各插件区分临时目录、路径分隔符时用）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">boolean</span> <span class="token function">isWinOS</span><span class="token punctuation">(</span><span class="token punctuation">)</span>

<span class="token comment">// NumUtil：进制转换</span>
<span class="token comment">// 支持十进制/八进制/十六进制字符串转 int（内部用 Long.decode，避免 0xffee0011 这类大数在 Integer 上溢出）</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Integer</span> <span class="token function">decode2int</span><span class="token punctuation">(</span><span class="token class-name">String</span> str<span class="token punctuation">,</span> <span class="token class-name">Integer</span> defaultValue<span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">toHex</span><span class="token punctuation">(</span><span class="token keyword">int</span> hex<span class="token punctuation">)</span>   <span class="token comment">// int 转 16 进制字符串，单位数补 0</span>

<span class="token comment">// ProcessUtil：执行外部命令</span>
<span class="token keyword">public</span> <span class="token keyword">boolean</span> <span class="token function">process</span><span class="token punctuation">(</span><span class="token class-name">String</span> cmd<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">Exception</span>

<span class="token comment">// 用法：ProcessUtil.instance().process(&quot;ffmpeg -i in.mp3 out.wav&quot;);</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>ProcessUtil</code> 内部是用线程池并行消费子进程的 stdout/stderr（防止大量输出导致死锁，参考 im4java 的实现），并给进程等待加了 2 秒的超时，防止外部命令卡死拖垮主流程。audio-plugin 调 ffmpeg 转码走的就是它。如果你的业务也需要 Java 里执行外部命令，这个类的实现值得抄一抄。</p><h2 id="_13-小结" tabindex="-1"><a class="header-anchor" href="#_13-小结" aria-hidden="true">#</a> 13. 小结</h2><p>base-plugin 没有什么黑科技，就是一个个短小、独立、以静态方法为主的工具类集合。理解它的最好方式是带着场景去翻对应的方法：</p><table><thead><tr><th style="text-align:center;">想做什么</th><th style="text-align:center;">找谁</th></tr></thead><tbody><tr><td style="text-align:center;">读本地/网络/classpath 的文件</td><td style="text-align:center;"><code>FileReadUtil</code></td></tr><tr><td style="text-align:center;">保存流/文本，建目录</td><td style="text-align:center;"><code>FileWriteUtil</code></td></tr><tr><td style="text-align:center;">判断文件类型（不看后缀）</td><td style="text-align:center;"><code>FileReadUtil.getMagicNum</code> + <code>MediaType</code></td></tr><tr><td style="text-align:center;">加载图片/ico/gif</td><td style="text-align:center;"><code>ImageLoadUtil</code></td></tr><tr><td style="text-align:center;">圆角、圆形 logo、边框</td><td style="text-align:center;"><code>ImageOperateUtil</code></td></tr><tr><td style="text-align:center;">拿高质量画笔画布、缩放、png 转 jpg</td><td style="text-align:center;"><code>GraphicUtil</code></td></tr><tr><td style="text-align:center;">各种格式的颜色互转</td><td style="text-align:center;"><code>ColorUtil</code></td></tr><tr><td style="text-align:center;">gif 拆帧、合成</td><td style="text-align:center;"><code>GifHelper</code>（底层 <code>GifDecoder</code>/<code>GifEncoder</code>）</td></tr><tr><td style="text-align:center;">下载网络资源</td><td style="text-align:center;"><code>HttpUtil</code></td></tr><tr><td style="text-align:center;">流重复消费</td><td style="text-align:center;"><code>IoUtil</code></td></tr><tr><td style="text-align:center;">base64、data-uri</td><td style="text-align:center;"><code>Base64Util</code> + <code>DomUtil</code></td></tr><tr><td style="text-align:center;">执行外部命令</td><td style="text-align:center;"><code>ProcessUtil</code></td></tr></tbody></table><p><strong>相关文档：</strong></p>`,69),v=n("strong",null,"项目地址：",-1),g={href:"https://github.com/liuyueyi/quick-media",target:"_blank",rel:"noopener noreferrer"};function b(f,y){const p=e("RouterLink"),c=e("ExternalLinkIcon");return l(),i("div",null,[r,u(" more "),m,n("ul",null,[n("li",null,[a(p,{to:"/git/quick-media/phantom/01.%E5%9F%BA%E4%BA%8EPhantomJs%E5%AE%9E%E7%8E%B0html%E8%BE%93%E5%87%BA%E5%9B%BE%E7%89%87.html"},{default:d(()=>[s("phantom-plugin：基于 PhantomJs 实现 html 输出图片")]),_:1})])]),n("p",null,[v,s(),n("a",g,[s("https://github.com/liuyueyi/quick-media"),a(c)])])])}const h=o(k,[["render",b],["__file","01.公共工具类速查.html.vue"]]);export{h as default};
